$function$

CREATE OR REPLACE FUNCTION semantic_atlas.read_current_runtime_objects_v1(p_authority_scope text, p_git_repository_locator text, p_git_ref text, p_git_readback_sha text, p_readback_at timestamp with time zone, p_readback_source text)
 RETURNS SETOF semantic_atlas.active_runtime_objects
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'semantic_atlas'
AS $function$
declare
  v_snapshot semantic_atlas.runtime_snapshots%rowtype;
  v_now timestamptz;
begin
  if p_authority_scope not in ('CANONICAL_LEDGER','RESEARCH_STAGING') then
    raise exception 'invalid runtime authority scope';
  end if;
  if p_git_repository_locator is null or length(p_git_repository_locator)=0
     or p_git_ref is null or length(p_git_ref)=0
     or p_git_readback_sha !~ '^[0-9a-f]{40}$'
  then
    raise exception 'current runtime read requires exact repository/ref/SHA readback';
  end if;
  if p_readback_source is null or length(p_readback_source)=0 then
    raise exception 'current runtime readback source required';
  end if;

  v_now:=statement_timestamp();
  if p_readback_at is null
     or p_readback_at<v_now-interval '60 seconds'
     or p_readback_at>v_now+interval '1 minute'
  then
    raise exception 'current runtime read requires provider readback within 60 seconds';
  end if;

  select * into v_snapshot
  from semantic_atlas.runtime_snapshots
  where authority_scope=p_authority_scope and state='ACTIVE';
  if not found then raise exception 'no active runtime snapshot for scope'; end if;

  if v_snapshot.git_repository_locator is distinct from p_git_repository_locator then
    raise exception 'active runtime repository does not match current provider readback';
  end if;
  if v_snapshot.git_ref is distinct from p_git_ref then
    raise exception 'active runtime ref does not match current provider readback';
  end if;
  if v_snapshot.git_commit_sha is distinct from p_git_readback_sha then
    raise exception 'active runtime snapshot is stale relative to current provider ref';
  end if;
  if p_readback_at<v_snapshot.activated_at then
    raise exception 'current provider readback predates runtime activation';
  end if;

  return query
  select *
  from semantic_atlas.active_runtime_objects
  where snapshot_id=v_snapshot.snapshot_id;
end;
$function$

CREATE OR REPLACE FUNCTION semantic_atlas.record_semantic_capture_outcome_v2(p_event_id uuid, p_action text, p_semantic_decider text, p_decision_payload jsonb DEFAULT '{}'::jsonb, p_git_commit_sha text DEFAULT NULL::text, p_git_object_refs jsonb DEFAULT '[]'::jsonb, p_git_authority_scope text DEFAULT NULL::text, p_git_ref text DEFAULT NULL::text, p_git_readback_sha text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'semantic_atlas'
AS $function$
declare v_outcome_id uuid;
begin
  if not exists(select 1 from semantic_atlas.semantic_capture_events where event_id=p_event_id) then raise exception 'semantic capture event not found'; end if;
  if p_action='GIT_WRITE_CONFIRMED' then
    if p_git_commit_sha is null or p_git_commit_sha !~ '^[0-9a-f]{40}$'
       or p_git_authority_scope not in ('CANONICAL_LEDGER','RESEARCH_STAGING')
       or p_git_ref is null or length(p_git_ref)=0
       or p_git_readback_sha is distinct from p_git_commit_sha
       or jsonb_typeof(coalesce(p_git_object_refs,'[]'::jsonb))<>'array'
       or jsonb_array_length(coalesce(p_git_object_refs,'[]'::jsonb))=0
    then raise exception 'GIT_WRITE_CONFIRMED requires exact commit, scope, ref, matching readback SHA, and object refs'; end if;
  end if;
  insert into semantic_atlas.semantic_capture_outcomes(
    event_id,action,semantic_decider,decision_payload,git_commit_sha,git_object_refs,
    git_authority_scope,git_ref,git_readback_sha,notes
  ) values (
    p_event_id,p_action,p_semantic_decider,coalesce(p_decision_payload,'{}'::jsonb),p_git_commit_sha,
    coalesce(p_git_object_refs,'[]'::jsonb),p_git_authority_scope,p_git_ref,p_git_readback_sha,p_notes
  ) returning outcome_id into v_outcome_id;
  return v_outcome_id;
end;
$function$

CREATE OR REPLACE FUNCTION semantic_atlas.seal_runtime_snapshot_v2(p_snapshot_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'semantic_atlas', 'extensions'
AS $function$
declare
  v_snapshot semantic_atlas.runtime_snapshots%rowtype;
  v_count integer;
  v_counts jsonb;
  v_pathset_stream text;
  v_object_stream text;
  v_manifest_stream text;
  v_pathset_sha text;
  v_snapshot_sha text;
  v_manifest_sha text;
  v_sealed_at timestamptz;
begin
  select * into v_snapshot from semantic_atlas.runtime_snapshots where snapshot_id=p_snapshot_id for update;
  if not found then raise exception 'runtime snapshot not found'; end if;
  if v_snapshot.state<>'LOADING' or v_snapshot.validation_state<>'UNVERIFIED' then raise exception 'runtime snapshot must be LOADING/UNVERIFIED before sealing'; end if;
  if v_snapshot.manifest_contract<>'SEMANTIC_ATLAS_RUNTIME_MANIFEST_V3' then raise exception 'unsupported runtime manifest contract'; end if;

  if exists(select 1 from semantic_atlas.runtime_objects where snapshot_id=p_snapshot_id and (payload_sha256<>encode(extensions.digest(convert_to(canonical_payload,'UTF8'),'sha256'),'hex') or payload<>canonical_payload::jsonb)) then raise exception 'runtime object canonical payload verification failed'; end if;
  select count(*)::integer into v_count from semantic_atlas.runtime_objects where snapshot_id=p_snapshot_id;
  if v_count<>v_snapshot.expected_object_count then raise exception 'runtime object count mismatch: expected %, observed %',v_snapshot.expected_object_count,v_count; end if;
  select coalesce(jsonb_object_agg(object_type,type_count),'{}'::jsonb) into v_counts from (select object_type,count(*)::integer type_count from semantic_atlas.runtime_objects where snapshot_id=p_snapshot_id group by object_type) q;

  select coalesce(string_agg(semantic_atlas.frame_utf8_v1(source_path),'' order by convert_to(source_path,'UTF8')),'') into v_pathset_stream
  from (select distinct source_path from semantic_atlas.runtime_objects where snapshot_id=p_snapshot_id) s;
  select coalesce(string_agg(
    semantic_atlas.frame_utf8_v1(source_path)||semantic_atlas.frame_utf8_v1(object_id)||semantic_atlas.frame_utf8_v1(object_type)||semantic_atlas.frame_utf8_v1(payload_sha256),
    '' order by convert_to(source_path,'UTF8'),convert_to(object_id,'UTF8')
  ),'') into v_object_stream from semantic_atlas.runtime_objects where snapshot_id=p_snapshot_id;

  v_pathset_sha:=encode(extensions.digest(convert_to(v_pathset_stream,'UTF8'),'sha256'),'hex');
  v_snapshot_sha:=encode(extensions.digest(convert_to(v_object_stream,'UTF8'),'sha256'),'hex');
  v_manifest_stream:=semantic_atlas.runtime_manifest_stream_v3(v_snapshot.authority_scope,v_snapshot.git_commit_sha,v_snapshot.git_ref,v_snapshot.source_branch,v_snapshot.materialization_version,v_count,v_object_stream);
  v_manifest_sha:=encode(extensions.digest(convert_to(v_manifest_stream,'UTF8'),'sha256'),'hex');

  if v_pathset_sha<>v_snapshot.pathset_sha256 then raise exception 'runtime pathset digest mismatch'; end if;
  if v_snapshot_sha<>v_snapshot.snapshot_sha256 then raise exception 'runtime materialization digest mismatch'; end if;
  if v_manifest_sha<>v_snapshot.manifest_sha256 then raise exception 'runtime reconstructed manifest digest mismatch'; end if;

  v_sealed_at:=clock_timestamp();
  perform set_config('semantic_atlas.runtime_mutation','on',true);
  update semantic_atlas.runtime_snapshots
  set state='SEALED',validation_state='VERIFIED',validated_at=v_sealed_at,sealed_at=v_sealed_at,object_counts=v_counts,
      activation_git_readback_sha=null,activation_git_readback_at=null,activation_git_readback_source=null
  where snapshot_id=p_snapshot_id;
end;
$function$

CREATE OR REPLACE FUNCTION semantic_atlas.seal_runtime_snapshot_v3(p_snapshot_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'semantic_atlas', 'extensions'
AS $function$
declare
  v_snapshot semantic_atlas.runtime_snapshots%rowtype;
  v_count integer;
  v_counts jsonb;
  v_pathset_stream text;
  v_object_stream text;
  v_manifest_stream text;
  v_pathset_sha text;
  v_snapshot_sha text;
  v_manifest_sha text;
  v_sealed_at timestamptz;
begin
  select * into v_snapshot from semantic_atlas.runtime_snapshots where snapshot_id=p_snapshot_id for update;
  if not found then raise exception 'runtime snapshot not found'; end if;
  if v_snapshot.state<>'LOADING' or v_snapshot.validation_state<>'UNVERIFIED' then raise exception 'runtime snapshot must be LOADING/UNVERIFIED before sealing'; end if;
  if v_snapshot.manifest_contract<>'SEMANTIC_ATLAS_RUNTIME_MANIFEST_V4' then raise exception 'unsupported runtime manifest contract'; end if;

  if exists(select 1 from semantic_atlas.runtime_objects where snapshot_id=p_snapshot_id and (payload_sha256<>encode(extensions.digest(convert_to(canonical_payload,'UTF8'),'sha256'),'hex') or payload<>canonical_payload::jsonb)) then raise exception 'runtime object canonical payload verification failed'; end if;
  select count(*)::integer into v_count from semantic_atlas.runtime_objects where snapshot_id=p_snapshot_id;
  if v_count<>v_snapshot.expected_object_count then raise exception 'runtime object count mismatch: expected %, observed %',v_snapshot.expected_object_count,v_count; end if;
  select coalesce(jsonb_object_agg(object_type,type_count),'{}'::jsonb) into v_counts from (select object_type,count(*)::integer type_count from semantic_atlas.runtime_objects where snapshot_id=p_snapshot_id group by object_type) q;

  select coalesce(string_agg(semantic_atlas.frame_utf8_v1(source_path),'' order by convert_to(source_path,'UTF8')),'') into v_pathset_stream
  from (select distinct source_path from semantic_atlas.runtime_objects where snapshot_id=p_snapshot_id) s;
  select coalesce(string_agg(
    semantic_atlas.frame_utf8_v1(source_path)||semantic_atlas.frame_utf8_v1(object_id)||semantic_atlas.frame_utf8_v1(object_type)||semantic_atlas.frame_utf8_v1(payload_sha256),
    '' order by convert_to(source_path,'UTF8'),convert_to(object_id,'UTF8')
  ),'') into v_object_stream from semantic_atlas.runtime_objects where snapshot_id=p_snapshot_id;

  v_pathset_sha:=encode(extensions.digest(convert_to(v_pathset_stream,'UTF8'),'sha256'),'hex');
  v_snapshot_sha:=encode(extensions.digest(convert_to(v_object_stream,'UTF8'),'sha256'),'hex');
  v_manifest_stream:=semantic_atlas.runtime_manifest_stream_v4(v_snapshot.authority_scope,v_snapshot.git_repository_locator,v_snapshot.git_commit_sha,v_snapshot.git_ref,v_snapshot.source_branch,v_snapshot.materialization_version,v_count,v_object_stream);
  v_manifest_sha:=encode(extensions.digest(convert_to(v_manifest_stream,'UTF8'),'sha256'),'hex');

  if v_pathset_sha<>v_snapshot.pathset_sha256 then raise exception 'runtime pathset digest mismatch'; end if;
  if v_snapshot_sha<>v_snapshot.snapshot_sha256 then raise exception 'runtime materialization digest mismatch'; end if;
