  ), strict_matches as materialized (
    select v.*,ts_rank_cd(v.vec,v_strict)::real as score,
      ((select count(*) from unnest(v_tokens) q where q=any(tsvector_to_array(v.vec)))::real/cardinality(v_tokens)::real)::real as coverage
